import express, { type NextFunction, type Request, type Response } from "express";
import { TaskManagementService } from "../application/services";
import { DomainError, ValidationError } from "../domain/errors";
import type { TaskFilter } from "../domain/repositories";
import { isTaskStatus, type Task, type TaskStatus } from "../domain/task";
import {
  InMemoryProjectRepository,
  InMemoryTaskRepository,
  InMemoryUserRepository,
} from "./inMemoryRepositories";

function bodyOf(req: Request): Record<string, unknown> {
  const b: unknown = req.body;
  return typeof b === "object" && b !== null ? (b as Record<string, unknown>) : {};
}

function str(value: unknown, field: string, required: boolean): string {
  if (value === undefined || value === null) {
    if (required) throw new ValidationError(`${field} is required`);
    return "";
  }
  if (typeof value !== "string") throw new ValidationError(`${field} must be a string`);
  return value;
}

function parseDate(value: unknown): Date | null {
  if (value === undefined || value === null) return null;
  if (typeof value !== "string") throw new ValidationError("dueDate must be an ISO date string");
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) throw new ValidationError("dueDate is invalid");
  return d;
}

function present(task: Task) {
  return { ...task, dueDate: task.dueDate ? task.dueDate.toISOString() : null };
}

export function createApp(service?: TaskManagementService): express.Express {
  const svc =
    service ??
    new TaskManagementService(
      new InMemoryUserRepository(),
      new InMemoryProjectRepository(),
      new InMemoryTaskRepository(),
    );
  const app = express();
  app.use(express.json());

  app.post("/users", (req, res) => {
    res.status(201).json(svc.createUser(str(bodyOf(req).name, "name", true)));
  });

  app.post("/projects", (req, res) => {
    res.status(201).json(svc.createProject(str(bodyOf(req).name, "name", true)));
  });

  app.get("/projects", (_req, res) => {
    res.json(svc.listProjects());
  });

  app.post("/projects/:projectId/tasks", (req, res) => {
    const b = bodyOf(req);
    let status: TaskStatus | undefined;
    if (b.status !== undefined) {
      if (!isTaskStatus(b.status)) throw new ValidationError("status must be todo, in_progress or done");
      status = b.status;
    }
    const assignee =
      b.assigneeId === undefined || b.assigneeId === null ? null : str(b.assigneeId, "assigneeId", true);
    const task = svc.createTask({
      projectId: String(req.params.projectId),
      title: str(b.title, "title", true),
      description: str(b.description, "description", false),
      dueDate: parseDate(b.dueDate),
      status,
      assigneeId: assignee,
    });
    res.status(201).json(present(task));
  });

  app.get("/projects/:projectId/tasks", (req, res) => {
    const filter: TaskFilter = {};
    const { status, assigneeId } = req.query;
    if (status !== undefined) {
      if (!isTaskStatus(status)) throw new ValidationError("status must be todo, in_progress or done");
      filter.status = status;
    }
    if (assigneeId !== undefined) {
      if (typeof assigneeId !== "string") throw new ValidationError("assigneeId must be a string");
      filter.assigneeId = assigneeId;
    }
    res.json(svc.listTasks(String(req.params.projectId), filter).map(present));
  });

  app.put("/tasks/:taskId/assignee", (req, res) => {
    const assigneeId = str(bodyOf(req).assigneeId, "assigneeId", true);
    res.json(present(svc.assignTask(String(req.params.taskId), assigneeId)));
  });

  app.post("/tasks/:taskId/done", (req, res) => {
    res.json(present(svc.markDone(String(req.params.taskId))));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof DomainError) {
      const status = err.code === "validation" ? 400 : err.code === "not_found" ? 404 : 409;
      res.status(status).json({ error: err.message });
      return;
    }
    if (err instanceof SyntaxError) {
      res.status(400).json({ error: "Invalid JSON body" });
      return;
    }
    res.status(500).json({ error: "Internal server error" });
  });

  return app;
}

